import sys

def min_operations_to_zero(n, a):
    result = []
    for num in a:
        if num == 0:
            result.append(0)
            continue
        count = 0
        while num != 0:
            if num % 2 == 0:
                num = (num * 2) % 32768
            else:
                num = (num + 1) % 32768
            count += 1
        result.append(count)
    return result

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))
    result = min_operations_to_zero(n, a)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
